from .syslog_entry import SyslogEntry


class FsyslogEntry(SyslogEntry):
    """
    Provides methods to parse and represent fsyslog entry objects in a readable format.
    """

    def __init__(self, source_ip_addr=None, **kwargs):
        super(FsyslogEntry, self).__init__(**kwargs)
        self.source_ip_addr = source_ip_addr
